fn find_smallest(s: Vec<i32>) -> i32 {
    // Since the problem guarantees s is non‐empty, it's safe to unwrap the first element.
    let mut iter = s.into_iter();
    let mut min_val = iter.next().unwrap();

    // Iterate through the rest of the elements,
    // maintaining that `min_val` is always ≤ every element seen so far
    // and equal to one of them.
    for x in iter {
        if x < min_val {
            min_val = x;
        }
    }

    min_val
}

